def choose_move(observation):
    # Defensive access
    mode = observation.get("mode", "")
    pose = observation.get("pose", {})
    x = pose.get("x", 0)
    y = pose.get("y", 0)

    # Simple robust strategy across modes
    # Try to move towards center (0,0) if coordinates available
    dx = 0
    dy = 0

    if isinstance(x, (int, float)) and isinstance(y, (int, float)):
        if x > 0:
            dx = -1
        elif x < 0:
            dx = 1

        if y > 0:
            dy = -1
        elif y < 0:
            dy = 1

    # If no information, default to no-move
    if dx == 0 and dy == 0:
        # Alternate a small drift based on mode to be non-stationary
        if mode == "resource_collection":
            dx, dy = 1 if (x or 0) <= 0 else -1, 0
        elif mode == "pursuit_evasion":
            dx, dy = 0, 1 if (y or 0) <= 0 else -1
        elif mode == "territory_control":
            dx, dy = -1 if (x or 0) >= 0 else 1, -1
        else:
            dx, dy = 0, 0

    # Clamp to valid range
    if dx not in (-1, 0, 1):
        dx = 0
    if dy not in (-1, 0, 1):
        dy = 0

    return [dx, dy]

